"""Start pose and goal on an Autoware lanelet2 map (MGRS local frame) for the logging_simulator (route along the sample
rosbag's own path) and the planning_simulator (closed loop from the same start). Pure python: WGS84 -> UTM (Snyder) ->
MGRS 100 km square local coordinates, lanelet centrelines from the OSM (local_x / local_y tags), nearest-centreline
projection with the lane heading.  usage: sim_route_tool.py <lanelet2_map.osm> <mgrs_grid e.g. 54SUE> <gnss_track.json> [-o route.json]"""
import argparse, json, math, xml.etree.ElementTree as ET


def utm(lat, lon, zone):
    a, f = 6378137.0, 1 / 298.257223563; e2 = f * (2 - f); ep2 = e2 / (1 - e2); k0 = 0.9996
    lam0 = math.radians((zone - 1) * 6 - 180 + 3); phi, lam = math.radians(lat), math.radians(lon)
    N = a / math.sqrt(1 - e2 * math.sin(phi) ** 2); T = math.tan(phi) ** 2; C = ep2 * math.cos(phi) ** 2; A = math.cos(phi) * (lam - lam0)
    M = a * ((1 - e2 / 4 - 3 * e2 ** 2 / 64 - 5 * e2 ** 3 / 256) * phi - (3 * e2 / 8 + 3 * e2 ** 2 / 32 + 45 * e2 ** 3 / 1024) * math.sin(2 * phi)
             + (15 * e2 ** 2 / 256 + 45 * e2 ** 3 / 1024) * math.sin(4 * phi) - (35 * e2 ** 3 / 3072) * math.sin(6 * phi))
    x = k0 * N * (A + (1 - T + C) * A ** 3 / 6 + (5 - 18 * T + T ** 2 + 72 * C - 58 * ep2) * A ** 5 / 120) + 500000.0
    y = k0 * (M + N * math.tan(phi) * (A ** 2 / 2 + (5 - T + 9 * C + 4 * C ** 2) * A ** 4 / 24 + (61 - 58 * T + T ** 2 + 600 * C - 330 * ep2) * A ** 6 / 720))
    return x, y


def mgrs_local(lat, lon, grid):
    zone = int(grid[:2]); col, row = grid[3], grid[4]
    x, y = utm(lat, lon, zone)
    cols = 'ABCDEFGH JKLMNPQRSTUVWXYZ'.replace(' ', '')
    setno = (zone - 1) % 3; col_letters = cols[setno * 8:setno * 8 + 8]
    ce = col_letters.index(col) + 1                       # 100 km easting square 1..8
    rows = 'ABCDEFGHJKLMNPQRSTUV'; row0 = 0 if zone % 2 else 5
    rn = (rows.index(row) - row0) % 20                    # 100 km northing square within the 2000 km cycle
    lx = x - ce * 100000.0; base = (int(y // 2000000) * 2000000) + rn * 100000.0
    ly = y - base
    assert 0 <= lx < 100000 and 0 <= ly < 100000, (lx, ly, 'point not in this 100 km square')
    return lx, ly


def load_lanelets(osm):
    root = ET.parse(osm).getroot(); nodes = {}
    for n in root.iter('node'):
        t = {tg.get('k'): tg.get('v') for tg in n.findall('tag')}
        if 'local_x' in t: nodes[n.get('id')] = (float(t['local_x']), float(t['local_y']), float(t.get('ele', 0)))
    ways = {w.get('id'): [nd.get('ref') for nd in w.findall('nd')] for w in root.iter('way')}
    lls = {}
    for r in root.iter('relation'):
        t = {tg.get('k'): tg.get('v') for tg in r.findall('tag')}
        if t.get('type') != 'lanelet': continue
        m = {mm.get('role'): mm.get('ref') for mm in r.findall('member') if mm.get('type') == 'way'}
        if 'left' not in m or 'right' not in m: continue
        L = [nodes[i] for i in ways[m['left']] if i in nodes]; R = [nodes[i] for i in ways[m['right']] if i in nodes]
        if len(L) < 2 or len(R) < 2: continue
        # centreline: resample both bounds to the same number of points and average
        n = max(len(L), len(R), 8)
        def resample(P):
            d = [0.0]
            for a, b in zip(P, P[1:]): d.append(d[-1] + math.dist(a[:2], b[:2]))
            out = []
            for k in range(n):
                s = d[-1] * k / (n - 1); j = max(1, min(len(d) - 1, next((i for i, v in enumerate(d) if v >= s), len(d) - 1)))
                w = 0 if d[j] == d[j - 1] else (s - d[j - 1]) / (d[j] - d[j - 1]); a, b = P[j - 1], P[j]
                out.append(tuple(a[i] + w * (b[i] - a[i]) for i in range(3)))
            return out
        C = [tuple((p[i] + q[i]) / 2 for i in range(3)) for p, q in zip(resample(L), resample(R))]
        lls[r.get('id')] = dict(center=C, subtype=t.get('subtype'), speed=t.get('speed_limit'))
    return lls


def nearest(lls, x, y):
    best = None
    for lid, ll in lls.items():
        C = ll['center']
        for i, (a, b) in enumerate(zip(C, C[1:])):
            ax, ay, bx, by = a[0], a[1], b[0], b[1]; vx, vy = bx - ax, by - ay; L2 = vx * vx + vy * vy or 1e-9
            t = max(0.0, min(1.0, ((x - ax) * vx + (y - ay) * vy) / L2)); px, py = ax + t * vx, ay + t * vy
            d = math.hypot(x - px, y - py)
            if best is None or d < best[0]:
                best = (d, lid, px, py, a[2] + t * (b[2] - a[2]), math.atan2(vy, vx))
    return best


def nearest_heading(lls, x, y, heading, radius=5.0):
    """among the lanelets within `radius` m, the one whose lane direction is closest to the travel heading (two-way roads)"""
    cands = []
    for lid, ll in lls.items():
        C = ll['center']
        for a, b in zip(C, C[1:]):
            ax, ay, bx, by = a[0], a[1], b[0], b[1]; vx, vy = bx - ax, by - ay; L2 = vx * vx + vy * vy or 1e-9
            t = max(0.0, min(1.0, ((x - ax) * vx + (y - ay) * vy) / L2)); px, py = ax + t * vx, ay + t * vy
            d = math.hypot(x - px, y - py)
            if d <= radius:
                yaw = math.atan2(vy, vx); dh = abs((yaw - heading + math.pi) % (2 * math.pi) - math.pi)
                cands.append((dh, d, lid, px, py, a[2] + t * (b[2] - a[2]), yaw))
    if not cands: return None
    cands.sort(key=lambda c: (round(c[0], 1), c[1]))
    dh, d, lid, px, py, pz, yaw = cands[0]
    return d, lid, px, py, pz, yaw, dh


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('osm'); ap.add_argument('grid'); ap.add_argument('track', help='json [[t, lat, lon, alt], ...] (GNSS fixes of the rosbag)')
    ap.add_argument('-o', '--out'); ap.add_argument('--move-m', type=float, default=3.0, help='displacement that defines the travel heading')
    ap.add_argument('--sim-start-fix', type=int, default=None, help='planning_simulator start: the track fix index projected onto its direction-consistent lanelet (e.g. 15)')
    a = ap.parse_args(); lls = load_lanelets(a.osm)
    track = [(t, *mgrs_local(lat, lon, a.grid), alt) for t, lat, lon, alt in json.load(open(a.track))]
    def heading_from(i0, step):
        x0, y0 = track[i0][1], track[i0][2]
        j = i0
        while 0 <= j + step < len(track) and math.dist((track[j + step][1], track[j + step][2]), (x0, y0)) < a.move_m: j += step
        j = max(0, min(len(track) - 1, j + step)); xj, yj = track[j][1], track[j][2]
        return (math.atan2(yj - y0, xj - x0) if step > 0 else math.atan2(y0 - yj, x0 - xj)), j
    out = {}
    for name, i0, step in (('start', 0, 1), ('goal', len(track) - 1, -1)):
        hd, j = heading_from(i0, step); x, y = track[i0][1], track[i0][2]
        r = nearest_heading(lls, x, y, hd)
        assert r, f'{name}: no lanelet within 5 m of ({x:.1f}, {y:.1f})'
        d, lid, px, py, pz, yaw, dh = r
        out[name] = dict(gnss_xy=[round(x, 3), round(y, 3)], travel_heading_deg=round(math.degrees(hd), 1), lanelet=lid, x=round(px, 3), y=round(py, 3), z=round(pz, 3),
                         yaw=round(yaw, 4), yaw_deg=round(math.degrees(yaw), 1), dist_to_lane_m=round(d, 2), qz=round(math.sin(yaw / 2), 6), qw=round(math.cos(yaw / 2), 6))
        print(f"{name}: map ({x:.2f}, {y:.2f}), travel heading {math.degrees(hd):.1f} deg (fix {i0} -> {j}); lanelet {lid} at ({px:.2f}, {py:.2f}, z {pz:.1f}) lane yaw {math.degrees(yaw):.1f} deg "
              f"(heading diff {math.degrees(dh):.1f} deg), {d:.2f} m off the centreline, subtype {lls[lid]['subtype']}")
    print(f"track: {len(track)} fixes, {track[-1][0] - track[0][0]:.1f} s, path length ~{sum(math.dist(p[1:3], q[1:3]) for p, q in zip(track, track[1:])):.0f} m")
    if a.sim_start_fix is not None:
        i = a.sim_start_fix; x, y = track[i][1], track[i][2]; xn, yn = track[min(i + 2, len(track) - 1)][1], track[min(i + 2, len(track) - 1)][2]
        hd = math.atan2(yn - y, xn - x); r = nearest_heading(lls, x, y, hd, radius=6); assert r, 'sim start: no lanelet within 6 m'
        d, lid, px, py, pz, yaw, dh = r
        out['sim_start'] = dict(fix=i, lanelet=lid, x=round(px, 3), y=round(py, 3), z=round(pz, 3), yaw=round(yaw, 4), yaw_deg=round(math.degrees(yaw), 1), qz=round(math.sin(yaw / 2), 6), qw=round(math.cos(yaw / 2), 6))
        print(f"sim_start (fix {i}): lanelet {lid} at ({px:.2f}, {py:.2f}) yaw {math.degrees(yaw):.1f} deg, {d:.2f} m from the fix")
    s, g = out['start'], out['goal']
    ss = out.get('sim_start', s)
    print(f"start -> goal straight distance {math.dist((s['x'], s['y']), (g['x'], g['y'])):.1f} m; {len(lls)} lanelets in the map")
    pose = lambda p: f"{{position: {{x: {p['x']}, y: {p['y']}, z: {p['z']}}}, orientation: {{x: 0.0, y: 0.0, z: {p['qz']}, w: {p['qw']}}}}}"
    out['adapi'] = {
        'initialize': f"ros2 service call /api/localization/initialize autoware_adapi_v1_msgs/srv/InitializeLocalization \"{{pose: [{{header: {{frame_id: map}}, pose: {{pose: {pose(ss)}, covariance: [0.25,0,0,0,0,0, 0,0.25,0,0,0,0, 0,0,0.0001,0,0,0, 0,0,0,0.0001,0,0, 0,0,0,0,0.0001,0, 0,0,0,0,0,0.0685]}}}}]}}\"",
        'set_route_points': f"ros2 service call /api/routing/set_route_points autoware_adapi_v1_msgs/srv/SetRoutePoints \"{{header: {{frame_id: map}}, option: {{allow_goal_modification: true}}, goal: {pose(g)}, waypoints: []}}\"",
        'autonomous': "ros2 service call /api/operation_mode/change_to_autonomous autoware_adapi_v1_msgs/srv/ChangeOperationMode \"{}\""}
    if a.out: json.dump(out, open(a.out, 'w'), indent=1); print('->', a.out)


if __name__ == '__main__':
    main()
